<div class="actions"><button type="button" class="btn alt" id="previous" style="visibility:hidden">Sebelumnya</button><button type="button" class="btn" id="next">Selanjutnya</button><button type="submit" class="btn hidden" id="send">Kirim Pengajuan</button></div></form>
<script>let step=0;const sections=[...document.querySelectorAll('[data-step]')],tabs=[...document.querySelectorAll('[data-step-nav]')],form=document.getElementById('applyForm');function show(){sections.forEach((s,i)=>s.classList.toggle('hidden',i!==step));tabs.forEach((s,i)=>s.classList.toggle('active',i===step));document.getElementById('previous').style.visibility=step?'visible':'hidden';document.getElementById('next').classList.toggle('hidden',step===2);document.getElementById('send').classList.toggle('hidden',step!==2);if(step===2){const entries=[...new FormData(form).entries()].filter(([k])=>k!=='_token'&&k!=='setuju');document.getElementById('review').textContent=entries.map(([k,v])=>`${k}: ${v instanceof File?(v.name||'Tidak ada berkas'):v}`).join('
');document.getElementById('review').style.whiteSpace='pre-wrap';}}document.getElementById('next').onclick=()=>{if(step===0){for(const input of sections[0].querySelectorAll('input,textarea,select'))if(!input.checkValidity()){input.reportValidity();return}}if(step<2)step++;show()};document.getElementById('previous').onclick=()=>{step=Math.max(0,step-1);show()};form.addEventListener('submit',()=>document.getElementById('send').disabled=true);show();</script>
